import asyncio
import os
import edge_tts

VOICE = "en-US-AndrewNeural"
RATE = "-10%"     # matches your Speech Rate Adjustment slider
PITCH = "-15Hz"    # matches your Pitch Adjustment slider
CLIP_SECONDS = 8.0   # safe now — end-time cutoff guarantees no clip exceeds this

# Add your sections in this dictionary format:
SECTIONS = {
    "section1": """Close your eyes for a moment and listen. Water. Wind. The cry of gulls over a narrow strip of sea where two continents almost touch. To your left, Europe. To your right, Asia. And in between, a strait so important that every empire in history has wanted to control it. Open your eyes. The skyline in front of you is unlike anything else on earth. Domes and minarets rise above rooftops that have been standing for centuries. The smell of salt is in the air. The sound of the water never stops. You don't know the name of this place yet. But you can feel that something enormous happened here. Emperors were crowned in this city and murdered in this same city, sometimes on the same throne. The largest Christian church ever built was turned into a mosque, then into a museum, then back into a mosque again. Viking warriors once stood guard over a Greek emperor inside a Roman palace. A plague killed half the population in a single year, and the city kept going. A cannon so large it took sixty oxen to drag it across the countryside was aimed at these walls — and finally broke them. This is a city that has been through everything. And it survived almost all of it. We've used advanced AI to bring ancient mosaics, Byzantine paintings, and Ottoman miniatures to life. So you won't just be hearing about this place. You'll be watching it move, breathe, and burn. Three names. One city. Three thousand years. The Greeks called it Byzantium. The Romans called it Constantinople. The world today calls it Istanbul. This is its entire history. In 23 minutes. Let's begin.""",

    "section2": """Before anyone built anything here, the geography was already making the decision. The Bosphorus is a narrow strip of water — just half a mile wide at its tightest point — connecting the Black Sea in the north to the Sea of Marmara in the south. Every ship carrying grain, timber, gold, or slaves had to pass through it. There was no other way. Whoever sat on the shore and watched that water go by could collect taxes, control trade, and hold the rest of the world at arm's length. This was not a place someone discovered by accident. It was a place that was always waiting to be found. In 657 BC, a Greek man named Byzas sailed here from the city of Megara. Before he left, he visited the oracle at Delphi — the most famous fortune teller in the ancient world — and asked where he should build his new city. The oracle told him to settle "opposite the blind." Byzas looked across the strait and understood immediately. The people who had settled on the eastern shore of the Bosphorus, in a place called Chalcedon, had somehow missed the far better ground on the western side. They were blind to what was right in front of them. Byzas took the western shore and named the settlement after himself. Byzantium. The city he built was not grand. Not yet. It was a trading port — modest, practical, and busy. Ships stopped here. Merchants paid fees. The city grew slowly and steadily, the way places do when they sit on top of something everyone else needs. For centuries, Byzantium lived quietly in the background of bigger stories. The Persians captured it. The Spartans held it. Alexander the Great marched past it. Eventually, like almost everything in the ancient world, it was absorbed into Rome. And that is when things got complicated. In 193 AD, a civil war tore through the Roman Empire. Several generals fought each other for the throne. Byzantium backed the wrong one. The winner, Emperor Septimius Severus, was furious. He besieged the city for three years, broke through the walls, tore down its defenses, and stripped it of its rights and privileges. He wanted to make an example of it. Then he looked around at what he had nearly destroyed, and changed his mind. He rebuilt it. Bigger. Better. A new hippodrome for chariot racing. New colonnaded streets. New walls. He understood, too late and too clearly, that you cannot simply erase a city in a place like this. The geography will not allow it. Byzantium recovered. It always did. But the decision that would truly change everything was still coming — and it would be made by a Roman emperor standing on these same shores, looking out at the same water, seeing something none of his predecessors had seen.""",

    "section3": """The man who changed everything did not look like a visionary at first. He looked like a general. In 324 AD, Constantine defeated his last rival, a man named Licinius, at the Battle of Chrysopolis — fought just across the strait from Byzantium, close enough that you could have watched it from the shore. When the battle was over, Constantine was the sole ruler of the entire Roman Empire. No more rivals. No more sharing power. The world was his. And the first thing he decided was that Rome was finished. Not destroyed. Not abandoned overnight. But finished as the center of things. The old city was too far west, too far from the empire's most dangerous borders, too wrapped up in its own traditions and its own powerful families. Constantine wanted something new. Something he could shape himself. He chose Byzantium. What happened next is one of the stranger images in all of ancient history. Constantine walked the future boundary of his new city on foot, holding a spear, dragging the tip along the ground to mark where the walls would go. His generals walked beside him, watching the line stretch further and further from the old city center. After a while, one of them worked up the courage to ask how much further he planned to go. Constantine said he would stop when the one leading him decided to stop. His generals looked at each other. No one was leading him. He kept walking. The walls he marked that day enclosed a city three times the size of old Byzantium. His advisors thought he had lost his mind. They were wrong. He had simply seen something they hadn't. On May 11, 330 AD, Constantinople — the city of Constantine — was officially dedicated as the new capital of the Roman Empire. What had been a modest port town of around 50,000 people became, almost overnight, the seat of the most powerful empire on earth. Senators were relocated from Rome. The imperial treasury moved. The court moved. The machinery of Roman power picked itself up and set itself down on the shores of the Bosphorus. Rome, the original, began to hollow out. Not immediately. Not all at once. But the weight of the empire had shifted east, and it would never fully shift back. Within 150 years, the western half of the Roman Empire would collapse entirely, eaten away by invasions and debt and political chaos. The eastern half, anchored by Constantinople, would survive for another thousand years. Constantine built something extraordinary. A city chosen with intention, planted in the right place, and given every advantage power could provide. What he could not build was a guarantee. And what was already moving toward his walls would test every stone of it.""",

    "section4": """While Rome was falling, Constantinople was building. By 500 AD, the city had grown to half a million people. That number is hard to hold in your head. At a time when most cities in Europe had a few thousand residents at most, Constantinople had half a million. It was the largest city on the continent by a distance that left everything else far behind. While Visigoths tore through the streets of old Rome and the western empire crumbled piece by piece, this city was constructing aqueducts to carry fresh water across miles of countryside, a hippodrome that could hold 100,000 screaming fans, and the most formidable set of walls the ancient world had ever seen. The Theodosian Walls went up in the early 400s — three separate layers of defense, a wide moat in front, 96 towers rising along the length of them. Attackers who got through the first wall still faced the second. Then the third. For a thousand years, no army would break through them. They were not just walls. They were a statement. But the greatest statement the city ever made was built in 537 AD, and it was not a wall. It was a ceiling. Emperor Justinian had been on the throne for over a decade when he ordered the construction of a new church on the city's highest hill. The Hagia Sophia. His engineers designed a central dome so wide and so tall that many believed it would collapse under its own weight before it was ever finished. They were wrong. When Justinian walked inside for the first time at the dedication ceremony, he stood in silence for a long moment, looked up at the dome floating above him, and reportedly whispered: "Solomon, I have surpassed you." He was comparing himself to the builder of the great temple in Jerusalem. He was not entirely wrong. The city Justinian ruled was something genuinely new in the world. Greek was its language. Roman law was its backbone. Christian faith was its soul. Historians would later call it Byzantium, to separate it from the Rome it had grown out of. But the people who lived there simply called themselves Romans. They had no sense that they were something different. They believed they were the continuation of everything that had come before. They were right. And that was also the problem. Because continuity breeds pride, and pride breeds blindness. In 532 AD — just five years before Hagia Sophia was completed — the city tore itself apart. Two chariot-racing gangs, the Blues and the Greens, turned a stadium rivalry into a full uprising. They burned half the city to the ground and nearly killed the emperor inside his own palace. Justinian survived. He rebuilt. He finished his church. Then the plague arrived. And nothing was ever the same again. The plague came by ship. In 541 AD, vessels arriving from Egypt docked in Constantinople's harbor carrying grain. They were also carrying something else. Within weeks, people across the city began to die. Fever first. Then swollen lumps under the arms and in the groin. Then death, usually within days. At its peak, 5,000 people were dying inside the walls every single day. The emperor Justinian caught it himself and survived, which his people took as a miracle. The tens of thousands who did not survive were not so lucky. The gravediggers ran out of places to put the bodies. Officials began stacking the dead inside the hollow towers of the sea walls, sealing them in, and moving on. The smell hung over the city for months. The empire Justinian had spent his life building never fully recovered. But the city endured. It always found a way. In 626 AD, it was tested again. The Avars attacked from the land side while Persian forces pushed from the sea. The emperor was away fighting on another front entirely, leaving the city in the hands of its Patriarch — a religious leader, not a soldier. He walked the walls carrying sacred icons, leading prayers while the harbor burned below him. The attack failed. The city held. But it had been closer than anyone wanted to admit. Then came the Arabs. Between 717 and 718 AD, the Umayyad Caliphate sent the largest force the city had ever faced. 200,000 soldiers camped outside the walls through an entire winter. Their fleet blockaded the harbor. Food inside the city ran low. The situation looked hopeless. But Constantinople had a secret weapon. Greek Fire — a liquid that burst into flame on contact with water and could not be put out. Byzantine ships sprayed it across the Arab fleet in the Golden Horn. The wooden boats burned down to the waterline. The army outside, starving and freezing after months of failure, eventually withdrew. The Caliphate never attacked Constantinople again. The walls held. They always held. Until the people who were supposed to be allies came through them instead.""",

    "section5": """In 1204, an army of Christian crusaders on their way to recapture Jerusalem made a detour. They were in debt, short on supplies, and someone offered them a deal. Take Constantinople first. Sort out Jerusalem later. For three days, soldiers who wore the cross on their armor looted the greatest Christian city in the world. They melted bronze statues for coins. They shipped sacred relics back to Venice in crates. They burned the imperial library — centuries of preserved knowledge — to keep themselves warm at night. The population fell from 400,000 to under 50,000. The Latin rulers who replaced the Byzantines lasted 57 years and left almost nothing behind. The Byzantines took their city back in 1261. But the city they got back was a shadow. And the shadow was shrinking.""",

    "section6": """By 1453, the Byzantine Empire was barely an empire at all. The city that had once governed half the known world now controlled a few miles of coastline and not much else. The land outside the walls had been lost piece by piece over the previous century. The population inside those walls was a fraction of what it had once been. The palaces were crumbling. The churches were underfunded. The imperial court was still holding ceremonies and wearing the old costumes, but everyone could see the truth. This was a civilization running on memory. Across the water, a 21-year-old sultan had other plans. Mehmed II had grown up hearing stories about Constantinople. As a boy, he had read everything he could find about the city — its history, its walls, its weaknesses. By the time he took power, taking Constantinople was not just a military goal. It was a personal obsession. He was going to be the one who finally did what the Arabs, the Avars, the Persians, and the crusaders had all attempted. He was going to break those walls. He commissioned a Hungarian engineer named Urban to build a cannon the world had never seen before. The barrel was 27 feet long. It fired stone balls weighing 1,200 pounds. Just moving it from where it was built to the walls of Constantinople took two months and sixty oxen. When it fired, the sound was heard from miles away. The walls that had stood for a thousand years began, for the first time, to crack. Inside the city, Emperor Constantine XI Palaiologos knew the numbers. He had around 7,000 defenders. Mehmed had over 80,000 soldiers outside the walls. Constantine sent letters to the kingdoms of Western Europe begging for help. He waited. No ships came. On the night of May 28, 1453, Constantine attended a final church service in Hagia Sophia. The building was packed. People who had not prayed together in years stood side by side in the candlelight. When it was over, the emperor embraced each of his commanders one by one. Then he removed his imperial insignia — the symbols of Rome, of Constantinople, of a civilization stretching back a thousand years — and walked out into the dark as a regular soldier. His body was never found. The walls fell the next morning. Mehmed rode through the broken gates, dismounted at the door of Hagia Sophia, and bent down to scoop a handful of dirt. He poured it over his turban in a gesture of humility before God. Then he walked inside and declared it a mosque. The Roman Empire, in every form it had ever taken, was over. Scholars who fled the city carried crates of Greek manuscripts to Italy. Historians still trace the beginning of the Renaissance partly to what those refugees brought with them. The city Mehmed renamed Istanbul was still the city Constantine had built — the same harbor, the same hills, the same strait between two worlds. But it had a new soul now. And that soul was just getting started.""",

    "section7": """Mehmed did not want an empty city. He wanted the greatest city in the world. Within months of the conquest, he began inviting people back. Greeks who had fled were encouraged to return. Armenians were brought in from other parts of the empire. Jewish families expelled from Spain in 1492 — tens of thousands of them, with nowhere else to go — were welcomed into Istanbul when most of Europe's doors were shut in their faces. Merchants, craftsmen, scholars, and traders arrived from every corner of the Ottoman world. Mehmed understood something that many conquerors never do. A city is not its buildings. It is its people. And a city without people is just a collection of walls. Within a single generation, Istanbul had become the most diverse city on earth. The buildings followed. Mehmed built his palace — the Topkapi — on the same promontory where Byzas had first looked out over the strait more than two thousand years earlier. His successor Suleiman the Magnificent went further. Under Suleiman, the empire reached its greatest size, stretching across three continents, and Istanbul sat at the center of all of it like the hub of a wheel. He commissioned the city's greatest architect, a man named Mimar Sinan, to leave his mark on the skyline. Sinan built over 300 structures across the empire in his lifetime. He considered the Süleymaniye Mosque, completed in 1557, to be his finest work. But when people asked him what he thought of Hagia Sophia — the great church turned mosque that had stood for a thousand years before he was born — he said it was the one building he could never surpass. Coming from the greatest architect of the age, that was not false modesty. At its peak, Istanbul had 700,000 people. It was the largest city west of China. Its markets sold silk from Persia, spices from India, gold from Africa, and grain from Ukraine. The Ottoman Empire looked, from the outside, completely unbreakable. But size is not the same as strength. And the cracks were already forming. In 1683, an Ottoman army marched all the way to Vienna and failed to take it. That failure mattered more than it seemed at the time. The empire had reached as far as it could go, and now it would begin, slowly, to come back. Trade routes were shifting to the Atlantic, cutting Istanbul out of the most profitable flows of global commerce. And inside the empire, a force that was supposed to be its greatest military asset was becoming its biggest problem. The Janissaries — elite soldiers originally loyal only to the sultan — had spent generations building political power. By the 1700s, they were making and unmaking sultans at will, answering to no one. By 1800, European diplomats were writing letters home calling the Ottoman Empire the sick man of Europe. The city that had terrified Christendom for centuries had become the prize everyone else was quietly planning to take.""",

    "section8": """The sick man of Europe made one final bet, and lost everything. When World War One broke out in 1914, the Ottoman Empire sided with Germany. It seemed like the stronger hand. It was not. By 1918, Germany had surrendered, the war was over, and Allied warships were sailing into the Bosphorus — the same strait that had defined this city since the beginning — and docking without resistance. British, French, and Italian officers moved into the grand hotels of the city. They ate in its restaurants, drank at the Pera Palace, and attended meetings where the future of the Ottoman Empire was being divided up like land at an auction. The sultanate that had ruled for 600 years was abolished in 1922. Not in battle. Not with fire. Just a vote, a document, and a sultan quietly leaving the city on a British warship in the middle of the night. The man who replaced him was nothing like him. Mustafa Kemal — later known as Atatürk, meaning Father of the Turks — had led the military resistance that pushed the Allied forces out and created the modern Republic of Turkey. He was decisive, ruthless, and completely clear about what he wanted. He wanted a new country that looked forward, not back. And to make that point as clearly as possible, he did not choose Istanbul as his capital. He chose Ankara. A small city in the middle of the Anatolian plateau. Unremarkable, inland, and carrying none of Istanbul's imperial weight. The message was unmistakable. The age of empires and sultans and golden-domed palaces was finished. Istanbul was left to figure out what it was without the government that had shaped it for centuries. For a while, it struggled. Then came the night that left a wound the city has never fully closed. On September 6, 1955, riots broke out across Istanbul. False news reports claimed that Greeks had bombed Atatürk's birthplace in the city of Thessaloniki. The story was not true. But the mobs that poured into the streets of Istanbul did not stop to check. They targeted Greek-owned businesses, Armenian churches, and Jewish homes. Thousands of properties were destroyed in a single night. Investigations years later found fingerprints connecting the riots to people inside the Turkish government itself. The effect was permanent. The Greeks, Armenians, and Jews who had called this city home for generations left. A city that had been genuinely cosmopolitan for 1,500 years became, within a single decade, almost entirely Muslim and Turkish. The diversity Mehmed had deliberately built was gone. And yet the city kept growing. By 1950, Istanbul had around one million people. Today it has fifteen million. It is Turkey's economic engine, its cultural heartbeat, the city every ambitious young Turk moves to. The skyline keeps changing. The energy never stops. But one question refuses to go away. In 2020, Hagia Sophia was converted from a museum back into a working mosque. Greeks mourned. Turks celebrated. UNESCO issued a statement of concern. And the building itself — which has been a church, a mosque, a museum, and a mosque again — stood exactly where it has always stood, on the hill above the Bosphorus, saying nothing and meaning everything. Whose history is it? The Greeks who built it? The Ottomans who transformed it? The Turks who inherited it? Or does it belong to everyone who has ever stood inside it and looked up? The city has never answered that question. It is still living inside it.""",

    "section9": """Stand on the Galata Bridge today and just look. To your left, a ferry is crossing from Europe to Asia, the same crossing people have been making on this water for three thousand years. Fishermen lean against the railing with their lines in the strait below, the same strait where Roman warships once patrolled and Arab fleets once burned. Behind you, the rooftops of the old city climb the hill. And on the skyline, side by side, the minarets of the Blue Mosque and the great dome of Hagia Sophia — a church, a mosque, a museum, a mosque again — rising together above everything, inseparable, as if the city itself refuses to choose between them. This is Istanbul. This is Constantinople. This is Byzantium. Three names. Three civilizations. Three completely different ideas about what this place was supposed to be. The Greeks saw a trading post on a perfect strait. The Romans saw the center of an empire. The Byzantines saw the capital of the Christian world. The Ottomans saw the throne of a new age. Every one of them was right. Every one of them was also wrong. Because this city has never fully belonged to any of them. It has always been bigger than whoever was ruling it at the time. For three thousand years it has been conquered and renamed, emptied and refilled, burned to the ground and rebuilt from the ashes. Plague killed half its people and it recovered. Crusaders looted its libraries and it survived. A cannon broke its walls after a thousand years and it kept going under a different name. The empire that replaced the empire that replaced the original settlers is now itself a memory. And the city is still here. What survives is not the Greeks' version of it, or the Romans', or the Byzantines', or the Ottomans'. What survives is the thing none of them created and none of them could destroy. The geography. The water. The narrow strip of sea between two continents that Byzas recognized, that Constantine understood, and that Mehmed could not resist. That is what this city is, underneath every name it has ever been given. No city on earth has been so many things to so many civilizations, and kept going anyway. If this journey through three thousand years felt like it moved fast — it did, and there is so much more buried in every era we touched. Hit like if you want to see more deep dives like this, and subscribe so you don't miss the next one. Drop in the comments the city you think deserves this treatment. We read every single one. As always, we'll see you in the past.""",
}


async def get_word_timestamps(text: str):
    communicate = edge_tts.Communicate(text, VOICE, rate=RATE, pitch=PITCH, boundary="WordBoundary")
    words = []
    async for chunk in communicate.stream():
        if chunk["type"] == "WordBoundary":
            # offset/duration are in 100-nanosecond units
            start = chunk["offset"] / 10_000_000
            duration = chunk["duration"] / 10_000_000
            end = start + duration
            words.append({"text": chunk["text"], "start": start, "end": end})
    return words


def split_into_clips(words, clip_seconds=CLIP_SECONDS):
    """
    A word is only added to the current clip if it FINISHES (end time)
    before the clip's time budget runs out. This guarantees the clip's
    actual spoken audio never exceeds clip_seconds — no word gets cut
    off mid-utterance, and no clip silently overruns the limit.
    """
    if not words:
        return []
    clips = []
    current_words = []
    clip_start = words[0]["start"]

    for w in words:
        if w["end"] - clip_start > clip_seconds and current_words:
            clips.append(current_words)
            current_words = []
            clip_start = w["start"]
        current_words.append(w["text"])

    if current_words:
        clips.append(current_words)

    return clips


async def main():
    # Ensure sections directory exists
    os.makedirs("sections", exist_ok=True)

    for section_name, text in SECTIONS.items():
        print(f"Processing '{section_name}'...")
        words = await get_word_timestamps(text)

        if not words:
            print(f"No word boundaries returned for '{section_name}' — check voice name / network access.")
            continue

        clips = split_into_clips(words)

        output_path = os.path.join("sections", f"{section_name}_clips.txt")

        with open(output_path, "w", encoding="utf-8") as f:
            f.write(f"Total words: {len(words)}\n")
            f.write(f"Total clips: {len(clips)}\n")
            f.write(f"Clip ceiling: {CLIP_SECONDS}s\n\n")

            # re-derive per-clip timing for verification by walking the word list again
            idx = 0
            for i, clip_words in enumerate(clips, 1):
                clip_word_objs = words[idx: idx + len(clip_words)]
                idx += len(clip_words)
                clip_start = clip_word_objs[0]["start"]
                clip_end = clip_word_objs[-1]["end"]
                duration = clip_end - clip_start

                text_clip = " ".join(clip_words)
                f.write(f"Clip {i} ({len(clip_words)} words, {duration:.2f}s):\n")
                f.write(text_clip + "\n\n")

        print(f"  Clips successfully saved to: {output_path}")


if __name__ == "__main__":
    asyncio.run(main())
